classDiagram
 direction TB
 class Account {
  +String email
  +signIn() bool
 }
 class Buyer {
  +String address
  +checkout()
 }
 class Order {
  +int number
  +submit()
 }
 class Line {
  +int quantity
  +subtotal() Money
 }
 class Payment {
  <<interface>>
  +authorize() bool
 }
 class Card {
  -String token
  +authorize() bool
 }
 Account <|-- Buyer
 Buyer "1" --> "*" Order : places
 Order "1" *-- "*" Line : contains
 Buyer o-- Card : stores
 Card ..|> Payment
 Order ..> Payment : charges
 Line -- Payment : refunds
 Account .. Payment : audits

erDiagram
 CUSTOMER {
  int id PK
  string email UK
  string name
 }
 ORDER {
  int id PK
  int customer_id FK
  date placed
 }
 LINE {
  int order_id PK, FK
  int product_id PK, FK
  int quantity
 }
 PRODUCT {
  int id PK
  string sku UK
  decimal price
 }
 PAYMENT {
  int id PK
  int order_id FK
  string status
 }
 CUSTOMER ||--o{ ORDER : places
 ORDER ||--|{ LINE : contains
 PRODUCT ||--o{ LINE : appears
 ORDER ||--o| PAYMENT : settles

requirementDiagram
 requirement safe {
  id: R1
  text: "No duplicate charge"
  risk: high
  verifymethod: test
 }
 performanceRequirement fast {
  id: R2
  text: "Checkout under 2s"
  risk: medium
  verifymethod: analysis
 }
 functionalRequirement receipt {
  id: R3
  text: "Email every receipt"
  risk: low
  verifymethod: demonstration
 }
 element api {
  type: "service"
  docref: "Order API"
 }
 element suite {
  type: "test"
  docref: "Payment tests"
 }
 api - satisfies -> safe
 api - satisfies -> fast
 api - satisfies -> receipt
 suite - verifies -> safe
 suite - verifies -> receipt

C4Deployment
 Person(buyer, "Buyer", "Customer")
 Deployment_Node(cloud, "Production", "Cloud") {
  Deployment_Node(edge, "Edge", "CDN") {
   Container(web, "Web app", "React")
  }
  Deployment_Node(app, "App cluster", "Linux") {
   Container(api, "Order API", "Node")
   Container(worker, "Worker", "Node")
  }
  Deployment_Node(data, "Data", "Managed") {
   ContainerDb(db, "Orders", "Postgres")
  }
 }
 System_Ext(bank, "Bank", "Payments")
 Rel(buyer, web, "Browses")
 Rel(web, api, "Calls", "HTTPS")
 Rel(api, worker, "Dispatches")
 Rel(worker, db, "Updates")
 Rel(api, bank, "Charges")

